     * @param string $prefix The prefix for the routes in the group.
     * @param callable $callback The callback function containing the routes.
     *
     * @return void
     */
    public function group(string $prefix, callable $callback): void
    {
        $router = new Router();
        $callback($router);
        foreach ($router->routes as $route) {
            $this->addRoute($route['method'], $prefix . $route['path'], $route['handler']);
        }
    }

